def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_defects = 0
    opp_defects = 0
    for me, opp in history:
        if me == 'D':
            my_defects += 1
        if opp == 'D':
            opp_defects += 1

    if opp_defects > n * 0.8:
        return 'D'

    retaliated = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i+1][1] == 'D':
            retaliated = True
            break

    if not retaliated and my_defects > 0:
        return 'D'

    recent_my_defects = 0
    start = max(0, n - 10)
    for i in range(start, n):
        if history[i][0] == 'D':
            recent_my_defects += 1
    if recent_my_defects >= 4:
        return 'C'

    last_me, last_opp = history[-1]

    if last_me == 'D':
        return 'C'

    if last_opp == 'D':
        consec = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                consec += 1
            else:
                break
        if consec >= 2:
            return 'D'
        if opp_defects <= max(2, n // 10):
            return 'C'
        return 'D'

    if opp_defects == 0:
        if n == 2:
            return 'D'
        return 'C'

    return 'C'
